#![allow(dead_code)]
use std::{hint::black_box,time::Instant};
use idenso::{dirac::GammaSimplifier,representations::Bispinor,shorthands::{chain::Chain,schoonschip::Schoonschip}};
use spenso::network::parsing::AtomStructureExt;
use symbolica::atom::{Atom,AtomCore,AtomView};
use serde_json::json;
pub use idenso::{W_,rep_symbols,shorthands};
mod bracket;
mod epsilon;
mod dots;
#[derive(Clone,Copy,Debug)]
enum Method {
 Clone,
 ContainsEpsilon,
 RepeatedIndices,
 Brackets,
 Dots,
 CopiedDots,
 DotNestedVectors,
 DotRedundantMetrics,
 DotVectorPowers,
 DotMetricPowers,
 DotMetricTraces,
 EpsilonCandidates,
 EpsilonFull,
 CopiedEpsilonFull,
 Schoonschip,
 Chainify,
 CollectChains,
 CollectGammaChains,
 GammaTerminal,
}
const METHODS:[Method;19]=[Method::Clone,Method::ContainsEpsilon,Method::RepeatedIndices,Method::Brackets,Method::Dots,Method::CopiedDots,Method::DotNestedVectors,Method::DotRedundantMetrics,Method::DotVectorPowers,Method::DotMetricPowers,Method::DotMetricTraces,Method::EpsilonCandidates,Method::EpsilonFull,Method::CopiedEpsilonFull,Method::Schoonschip,Method::Chainify,Method::CollectChains,Method::CollectGammaChains,Method::GammaTerminal];
enum Outcome { Atom(Atom), Boolean(bool), Candidate(Atom,bool) }
fn run(method:Method,view:AtomView<'_>)->Outcome {
 use Method::*;
 match method {
  ContainsEpsilon=>return Outcome::Boolean(epsilon::contains(view)),
  RepeatedIndices=>return Outcome::Boolean(view.has_repeated_explicit_indices()),
  EpsilonCandidates=>{let(a,b)=epsilon::candidate_walk(view);return Outcome::Candidate(a,b)},
  _=>{}
 }
 Outcome::Atom(match method {
  Clone=>view.to_owned(),
  Brackets=>bracket::BracketNormalizer::normalize(view),
  Dots=>view.normalize_dots(),
  CopiedDots=>dots::DotNormalizer::run(view),
  DotNestedVectors=>dots::nested_vectors(view),
  DotRedundantMetrics=>dots::redundant_metrics(view),
  DotVectorPowers=>dots::vector_powers(view),
  DotMetricPowers=>dots::metric_powers(view),
  DotMetricTraces=>dots::metric_traces(view),
  EpsilonFull=>idenso::epsilon::EpsilonSimplifier::simplify_epsilon(&view),
  CopiedEpsilonFull=>epsilon::EpsilonSimplifier::simplify_epsilon(&view),
  Schoonschip=>view.schoonschip(),
  Chainify=>view.chainify(Bispinor{}.into()),
  CollectChains=>view.collect_chains(Bispinor{}.into()),
  CollectGammaChains=>view.collect_gamma_chains(),
  GammaTerminal=>view.simplify_gamma(),
  _=>unreachable!()
 })
}
fn batch(method:Method,input:&Atom,repetitions:usize)->f64 {
 let start=Instant::now();
 for _ in 0..repetitions {drop(black_box(run(method,black_box(input.as_view()))));}
 start.elapsed().as_nanos() as f64/repetitions as f64
}
fn main(){
 idenso::representations::initialize();
 let _=*epsilon::EPSILON_SYMBOL;
 let requested_rounds=std::env::args().nth(1).map_or(7,|s|s.parse().unwrap());
 let mut cases=Vec::new();
 for length in [6,8,10,12] {
  let path=format!("/tmp/gamma-cleanup-improvements/after-output/axial_{length}.input");
  let input=Atom::parse(&std::fs::read_to_string(&path).unwrap(),"spenso",symbolica::parser::ParseSettings::symbolica()).unwrap();
  let mut nodes=0usize;input.as_view().visitor(&mut |_|{nodes+=1;true});
  for method in METHODS {
   match run(method,input.as_view()) {
    Outcome::Atom(ref a)=>assert_eq!(a,&input,"{method:?}/{length} changed terminal output"),
    Outcome::Boolean(value)=>assert_eq!(value,matches!(method,Method::ContainsEpsilon)),
    Outcome::Candidate(ref a,changed)=>{assert_eq!(a,&input);assert!(!changed);},
   }
  }
  cases.push((length,input,nodes));
 }
 let mut repetitions=vec![vec![1;METHODS.len()];cases.len()];
 for (case,(_,input,_)) in cases.iter().enumerate(){
  for (m,method) in METHODS.iter().enumerate(){
   let estimate=batch(*method,input,1).max(1.0);
   repetitions[case][m]=((10_000_000.0/estimate) as usize).clamp(1,100_000);
  }
 }
 for round in 0..requested_rounds{
  for offset in 0..cases.len(){
   let case=(round+offset)%cases.len();let(length,input,nodes)=&cases[case];
   for moffset in 0..METHODS.len(){
    let m=(round+moffset)%METHODS.len();let method=METHODS[m];let reps=repetitions[case][m];
    let ns=batch(method,input,reps);
    println!("{}",json!({"case":format!("axial_{length}"),"method":format!("{method:?}"),"round":round,"repetitions":reps,"ns_per_call":ns,"top_terms":input.nterms(),"nodes":nodes,"unchanged":true}));
   }
  }
 }
}

reproduction_sources.bracket.rs:
use spenso::{
    bracket,
    network::{
        parsing::{AtomStructureExt, StructureInferenceMode},
        tags::SPENSO_TAG,
    },
    structure::{
        OrderedStructure,
        abstract_index::AbstractIndex,
        representation::{LibraryRep, Representation},
        slot::Slot,
    },
};
use symbolica::atom::{Atom, AtomCore, AtomView};

/// Expose a bracket's factors to ordinary product identities without erasing
/// the scope of an unresolved indexed product (in particular under a power).
pub(crate) struct BracketNormalizer;

impl BracketNormalizer {
    pub(crate) fn normalize(expression: AtomView<'_>) -> Atom {
        expression.replace_map_bottom_up(|node, _context, out| {
            if let AtomView::Mul(factors) = node {
                if factors
                    .iter()
                    .any(|factor| Self::open_payload(factor).is_some())
                {
                    let product = factors.iter().fold(Atom::one(), |product, factor| {
                        product * Self::open_payload(factor).unwrap_or(factor)
                    });
                    **out = Self::scoped_product(product);
                }
                return;
            }
            let AtomView::Fun(function) = node else {
                return;
            };
            if function.get_symbol() != SPENSO_TAG.bracket || function.get_nargs() == 0 {
                return;
            }
            if function.iter().any(|factor| factor.is_zero()) {
                **out = Atom::Zero;
                return;
            }
            // Unnamed ports still depend on operand order. Only explicitly
            // wired operands have an equivalent commutative Einstein product.
            if function.iter().any(Self::has_implicit_ports) {
                return;
            }
            let product = function.iter().fold(Atom::one(), |product, factor| {
                product * Self::open_payload(factor).unwrap_or(factor)
            });
            **out = Self::scoped_product(product);
        })
    }

    fn open_payload(expression: AtomView<'_>) -> Option<AtomView<'_>> {
        let AtomView::Fun(function) = expression else {
            return None;
        };
        if function.get_symbol() != SPENSO_TAG.bracket || function.get_nargs() != 1 {
            return None;
        }
        let payload = function.iter().next()?;
        if Self::has_implicit_ports(payload) {
            return None;
        }
        // Fast inference returns EmptyStructure for a scalar. Its contracted
        // indices belong to a closed scope and must not join the outer product.
        payload
            .infer_structure::<OrderedStructure>(StructureInferenceMode::Fast)
            .ok()?;
        Some(payload)
    }

    fn scoped_product(product: Atom) -> Atom {
        // A single tensor function is already atomic. Scalar coefficients can
        // leave the bracket, but two unresolved indexed factors must stay in
        // one scope: (sum_i A_i B_i)^n is not sum_i A_i^n B_i^n.
        let mut coefficient = Atom::one();
        let mut tensors = Vec::new();
        let mut classify = |factor: AtomView<'_>| {
            if Self::contains_indices(factor) {
                tensors.push(factor.to_owned());
            } else {
                coefficient *= factor;
            }
        };
        if let AtomView::Mul(factors) = product.as_view() {
            for factor in factors {
                classify(factor);
            }
        } else {
            classify(product.as_view());
        }
        let payload = tensors
            .iter()
            .fold(Atom::one(), |product, factor| product * factor);
        if tensors.len() > 1 || matches!(payload.as_view(), AtomView::Add(_) | AtomView::Pow(_)) {
            coefficient * bracket!(payload)
        } else {
            coefficient * payload
        }
    }

    fn has_implicit_ports(expression: AtomView<'_>) -> bool {
        match expression {
            AtomView::Fun(function) => {
                let symbol = function.get_symbol();
                if symbol.is_scalar() {
                    return false;
                }
                if symbol == SPENSO_TAG.bracket {
                    return function.iter().any(Self::has_implicit_ports);
                }
                function
                    .iter()
                    .skip(usize::from(symbol == SPENSO_TAG.trace))
                    .any(|argument| {
                        Representation::<LibraryRep>::try_from(argument).is_ok()
                            && Slot::<LibraryRep, AbstractIndex>::try_from(argument).is_err()
                    })
            }
            AtomView::Mul(product) => product.iter().any(Self::has_implicit_ports),
            AtomView::Add(sum) => sum.iter().any(Self::has_implicit_ports),
            AtomView::Pow(power) => Self::has_implicit_ports(power.get_base_exp().0),
            _ => false,
        }
    }

    fn contains_indices(expression: AtomView<'_>) -> bool {
        let mut found = false;
        expression.visitor(&mut |node| {
            if let AtomView::Fun(function) = node {
                if function.get_symbol().is_scalar() {
                    return false;
                }
                found |= function.get_symbol().has_attributes_of(SPENSO_TAG.rep_)
                    && function.get_nargs() == 2;
            }
            !found
        });
        found
    }
}

