use std::sync::LazyLock;

use spenso::{
    dot, dualizable_, dualizable_dual_, g,
    network::{library::symbolic::ETS, tags::SPENSO_TAG as T},
    rank1_, rep_, self_dual_,
    structure::abstract_index::AIND_SYMBOLS,
};
use symbolica::{
    atom::{Atom, AtomCore, AtomView},
    function,
    id::Replacement,
};

use crate::{W_, rep_symbols::RS, shorthands::metric::not_slot};

static ASYMMETRIC_SCHOONSCHIP_VECTOR_IN_VECTOR: LazyLock<[Replacement; 1]> = LazyLock::new(|| {
    let stripped = rep_!(0; W_.d_);
    // A stripped representation identifies the inner vector even when its
    // Symbolica head was not registered with a rank-one tensor tag.
    let inner = function!(RS.f_, RS.a___, &stripped);

    [
        //  p(...,q(..,rep)) is asymmetric, so we replace it with a dot product, using a schoonschiped metric:
        //  p(...,q(..,rep)) => g(p(...,rep), q(..,rep))
        Replacement::new(
            rank1_!(0; W_.c___, &inner).to_pattern(),
            g!(rank1_!(0; W_.c___, &stripped), inner,),
        )
        .when(not_slot(RS.a___))
        .min_level(0)
        .max_level(0)
        .level_is_tree_depth(true),
    ]
});

static REDUNDANT_METRIC_SCHOONSCHIPS: LazyLock<[Replacement; 4]> = LazyLock::new(|| {
    let self_dual = self_dual_!(0; W_.d_, W_.i_);
    let self_dual_stripped = self_dual_!(0; W_.d_);
    let dualizable = dualizable_!(0; W_.d_, W_.i_);
    let dualizable_stripped = dualizable_!(0; W_.d_);
    let dualizable_dual = dualizable_dual_!(0; W_.d_, W_.i_);

    [
        // g(mu,p(...,rep)) is redundant:
        // g(mu,p(...,rep)) => p(...,mu)
        Replacement::new(
            g!(&self_dual, rank1_!(0; W_.c___, self_dual_stripped)).to_pattern(),
            rank1_!(0; W_.c___, self_dual.clone()),
        ),
        // Same thing but for dualizable
        Replacement::new(
            g!(
                &dualizable,
                rank1_!(0; W_.c___, dualizable_stripped.clone())
            )
            .to_pattern(),
            rank1_!(0; W_.c___, dualizable),
        ),
        // Same thing but for dual dualizable
        Replacement::new(
            g!(&dualizable_dual, rank1_!(0; W_.c___, dualizable_stripped)).to_pattern(),
            rank1_!(0; W_.c___, dualizable_dual),
        ),
        // g(mu,p(...)) is also allowed (although a bit weird), here we normalize it to p(...,mu)
        Replacement::new(
            g!(&self_dual, rank1_!(0; W_.c___)).to_pattern(),
            rank1_!(0; W_.c___, self_dual),
        ),
    ]
    .map(|replacement| {
        replacement
            .min_level(0)
            .max_level(0)
            .level_is_tree_depth(true)
    })
});

static METRIC_DOT_PRODUCT: LazyLock<[Replacement; 2]> = LazyLock::new(|| {
    let self_dual_stripped1 = self_dual_!(0; W_.d_);
    let self_dual_stripped2 = self_dual_!(0; W_.e_);
    let dualizable_stripped1 = dualizable_!(0; W_.d_);
    let dualizable_stripped2 = dualizable_!(0; W_.e_);

    [
        Replacement::new(
            g!(
                rank1_!(0; W_.d___, &self_dual_stripped1),
                function!(RS.f_, RS.a___, &self_dual_stripped2)
            )
            .to_pattern(),
            dot!(
                rank1_!(0; W_.d___, self_dual_stripped1),
                function!(RS.f_, RS.a___, self_dual_stripped2)
            ),
        )
        .when(not_slot(RS.a___)),
        Replacement::new(
            g!(
                rank1_!(0; W_.d___, &dualizable_stripped1),
                function!(RS.f_, RS.a___, &dualizable_stripped2)
            )
            .to_pattern(),
            dot!(
                rank1_!(0; W_.d___, dualizable_stripped1),
                function!(RS.f_, RS.a___, dualizable_stripped2)
            ),
        )
        .when(not_slot(RS.a___)),
    ]
});

static VECTOR_POWER_NORMALIZATIONS: LazyLock<[Replacement; 2]> = LazyLock::new(|| {
    let self_dual = T.self_dual_::<0, _>([W_.d_, W_.i_]);
    let self_dual_stripped = T.self_dual_::<0, _>([W_.d_]);
    let self_dual_vector = T.rank1_::<0, _>([&Atom::var(W_.c___), &self_dual]);
    let self_dual_square = g!(
        T.rank1_::<0, _>([&Atom::var(W_.c___), &self_dual_stripped]),
        T.rank1_::<0, _>([&Atom::var(W_.c___), &self_dual_stripped]),
    );

    [
        // Normalize even powers of a vector p(...,mu)^2n -> g(p(...,rep),p(...,rep))^(n/2)
        Replacement::new(
            self_dual_vector.clone().pow(Atom::var(W_.n_)).to_pattern(),
            self_dual_square.pow(Atom::var(W_.n_) / 2),
        )
        .when(W_.n_.filter(DotNormalizer::even_power)),
        // Normalize odd powers of a vector p(...,mu)^(2n+1) -> p(...,mu) * g(p(...,rep),p(...,rep))^(n/2)
        Replacement::new(
            self_dual_vector.clone().pow(Atom::var(W_.n_)).to_pattern(),
            self_dual_square.pow((Atom::var(W_.n_) - 1) / 2) * self_dual_vector,
        )
        .when(W_.n_.filter(DotNormalizer::odd_power)),
    ]
});

static METRIC_POWER_NORMALIZATIONS: LazyLock<[Replacement; 2]> = LazyLock::new(|| {
    let self_dual = T.self_dual_::<0, _>([W_.d_, W_.i_]);
    let self_dual_j = T.self_dual_::<0, _>([W_.d_, W_.j_]);
    let self_dual_metric = g!(&self_dual, &self_dual_j);

    [
        // Normalize even powers of a metric g(rep(dim,i),rep(dim,j))^2n -> dim^(n/2)
        Replacement::new(
            self_dual_metric.pow(Atom::var(W_.n_)).to_pattern(),
            Atom::var(W_.d_).pow(Atom::var(W_.n_) / 2),
        )
        .when(W_.n_.filter(DotNormalizer::even_power)),
        // Normalize odd powers of a metric g(rep(dim,i),rep(dim,j))^(2n+1) -> dim^(n/2) * g(rep(dim,i),rep(dim,j))
        Replacement::new(
            self_dual_metric.pow(Atom::var(W_.n_)).to_pattern(),
            Atom::var(W_.d_).pow((Atom::var(W_.n_) - 1) / 2) * &self_dual_metric,
        )
        .when(W_.n_.filter(DotNormalizer::odd_power)),
    ]
});

static METRIC_TRACE_NORMALIZATIONS: LazyLock<[Replacement; 2]> = LazyLock::new(|| {
    let self_dual = T.self_dual_::<0, _>([W_.d_, W_.i_]);
    let dualizable = T.dualizable_::<0, _>([W_.d_, W_.i_]);
    let dualizable_dual = T.dualizable_dual_::<0, _>([W_.d_, W_.i_]);

    [
        // g(i,i) -> d
        Replacement::new(g!(&self_dual, &self_dual).to_pattern(), Atom::var(W_.d_)),
        // g(i,dind(i)) -> d
        Replacement::new(
            g!(&dualizable, &dualizable_dual).to_pattern(),
            Atom::var(W_.d_),
        ),
    ]
});

pub(crate) struct DotNormalizer;

impl DotNormalizer {
    pub(super) fn run(view: AtomView<'_>) -> Atom {
        // Traverse once per stage and only invoke the matcher at eligible roots.
        // Ordinary momentum components and scalar products need no wildcard
        // matching. Keep the original top-down traversal and stage ordering:
        // metric powers must be normalized before their traces, for example.
        // Inspect all arguments because symmetric heads can permute their slots.
        let mut current = view.replace_map(|atom, _context, out| {
            let AtomView::Fun(fun) = atom else { return };
            if fun.get_symbol().has_tag(&T.rank1)
                && fun.iter().any(|arg| {
                    matches!(arg, AtomView::Fun(inner)
                        if inner.iter().any(|arg| matches!(arg, AtomView::Fun(rep)
                                if rep.get_symbol().has_tag(&T.representation))))
                })
            {
                let mut replaced = Atom::new();
                if atom
                    .replace_multiple_into(&*ASYMMETRIC_SCHOONSCHIP_VECTOR_IN_VECTOR, &mut replaced)
                {
                    **out = replaced;
                }
            }
        });
        current.repeat_map(|view| {
            view.replace_map(|atom, _context, out| {
                let AtomView::Fun(fun) = atom else { return };
                if fun.get_symbol() == ETS.metric
                    && fun.iter().any(|arg| {
                        matches!(arg, AtomView::Fun(rep)
                        if rep.get_symbol().has_tag(&T.representation)
                            || rep.get_symbol() == AIND_SYMBOLS.dind)
                    })
                {
                    let mut replaced = Atom::new();
                    if atom.replace_multiple_into(&*REDUNDANT_METRIC_SCHOONSCHIPS, &mut replaced) {
                        **out = replaced;
                    }
                }
            })
        });
        current
            .replace_multiple(&*VECTOR_POWER_NORMALIZATIONS)
            .replace_multiple(&*METRIC_POWER_NORMALIZATIONS)
            .replace_multiple(&*METRIC_TRACE_NORMALIZATIONS)
    }

    pub(crate) fn metric_shorthand_to_dot(view: AtomView<'_>) -> Atom {
        view.to_owned().replace_multiple(&*METRIC_DOT_PRODUCT)
    }

    fn even_power(exp: AtomView<'_>) -> bool {
        matches!(i64::try_from(exp), Ok(exp) if exp % 2 == 0)
    }

    fn odd_power(exp: AtomView<'_>) -> bool {
        matches!(i64::try_from(exp), Ok(exp) if exp % 2 == 1)
    }
}


pub(crate) fn nested_vectors(view: AtomView<'_>) -> Atom {
view.replace_map(|atom, _context, out| {
            let AtomView::Fun(fun) = atom else { return };
            if fun.get_symbol().has_tag(&T.rank1)
                && fun.iter().any(|arg| {
                    matches!(arg, AtomView::Fun(inner)
                        if inner.iter().any(|arg| matches!(arg, AtomView::Fun(rep)
                                if rep.get_symbol().has_tag(&T.representation))))
                })
            {
                let mut replaced = Atom::new();
                if atom
                    .replace_multiple_into(&*ASYMMETRIC_SCHOONSCHIP_VECTOR_IN_VECTOR, &mut replaced)
                {
                    **out = replaced;
                }
            }
        })
}

pub(crate) fn redundant_metrics(view: AtomView<'_>) -> Atom {
 let mut current=view.to_owned();
        current.repeat_map(|view| {
            view.replace_map(|atom, _context, out| {
                let AtomView::Fun(fun) = atom else { return };
                if fun.get_symbol() == ETS.metric
                    && fun.iter().any(|arg| {
                        matches!(arg, AtomView::Fun(rep)
                        if rep.get_symbol().has_tag(&T.representation)
                            || rep.get_symbol() == AIND_SYMBOLS.dind)
                    })
                {
                    let mut replaced = Atom::new();
                    if atom.replace_multiple_into(&*REDUNDANT_METRIC_SCHOONSCHIPS, &mut replaced) {
                        **out = replaced;
                    }
                }
            })
        });

current
}

pub(crate) fn vector_powers(view:AtomView<'_>)->Atom { view.to_owned().replace_multiple(&*VECTOR_POWER_NORMALIZATIONS) }

pub(crate) fn metric_powers(view:AtomView<'_>)->Atom { view.to_owned().replace_multiple(&*METRIC_POWER_NORMALIZATIONS) }

pub(crate) fn metric_traces(view:AtomView<'_>)->Atom { view.to_owned().replace_multiple(&*METRIC_TRACE_NORMALIZATIONS) }

reproduction_sources.epsilon.rs:
use spenso::{
    g,
    network::parsing::{AtomStructureExt, StrictTensorFilter},
    structure::{
        abstract_index::AbstractIndex,
        dimension::Dimension,
        representation::{LibraryRep, RepName, Representation},
        slot::Slot,
    },
    tensor_symbol,
};
use symbolica::{
    atom::{Atom, AtomCore, AtomOrView, AtomView, FunctionBuilder, Symbol},
    coefficient::CoefficientView,
};

use crate::shorthands::schoonschip::Schoonschip;

spenso::symbolica_init_lazy_static! {
    /// Symbolica-level Levi-Civita symbol. The `Antisymmetric` attribute lets
    /// Symbolica canonicalize argument order and annihilate repeated arguments.
    pub static EPSILON_SYMBOL, EPSILON_SYMBOL_INNER: Symbol =
        || tensor_symbol!("spenso::epsilon"; Antisymmetric);
}

/// Builds an antisymmetric epsilon tensor with arbitrary rank.
pub fn epsilon<'a, F>(factors: impl IntoIterator<Item = F>) -> Atom
where
    F: Into<AtomOrView<'a>>,
{
    factors
        .into_iter()
        .fold(FunctionBuilder::new(*EPSILON_SYMBOL), |builder, factor| {
            builder.add_arg(factor)
        })
        .finish()
}

/// Builds an antisymmetric epsilon tensor with arbitrary rank.
///
/// Arguments are converted through `spenso::shadowing::IntoAtom`, so tests
/// and rewrite code can pass slots, atoms, atom views, symbols, and integers
/// without spelling out the conversion.
#[macro_export]
macro_rules! epsilon {
    (; $factors:expr $(,)?) => {
        $crate::epsilon::epsilon(($factors).into_iter())
    };
    ($($arg:expr),* $(,)?) => {{
        let builder = symbolica::atom::FunctionBuilder::new(*$crate::epsilon::EPSILON_SYMBOL);
        $(
            let builder = builder.add_arg(spenso::shadowing::IntoAtom::into_atom($arg));
        )*
        builder.finish()
    }};
}

/// Builds a four-dimensional Levi-Civita tensor.
pub fn epsilon4<'a, 'b, 'c, 'd>(
    mu: impl Into<AtomOrView<'a>>,
    nu: impl Into<AtomOrView<'b>>,
    rho: impl Into<AtomOrView<'c>>,
    sigma: impl Into<AtomOrView<'d>>,
) -> Atom {
    FunctionBuilder::new(*EPSILON_SYMBOL)
        .add_arg(mu)
        .add_arg(nu)
        .add_arg(rho)
        .add_arg(sigma)
        .finish()
}

/// Simplifies epsilon-metric contractions and epsilon-pair contractions.
pub trait EpsilonSimplifier {
    fn simplify_epsilon(&self) -> Atom;
}

impl EpsilonSimplifier for Atom {
    fn simplify_epsilon(&self) -> Atom {
        self.as_view().simplify_epsilon()
    }
}

impl EpsilonSimplifier for AtomView<'_> {
    fn simplify_epsilon(&self) -> Atom {
        EpsilonSimplifierPass::run(*self)
    }
}

struct EpsilonSimplifierPass;

impl EpsilonSimplifierPass {
    /// Runs the epsilon identities to a fixed point, then lets metric
    /// simplification consume any determinants that collapsed to traces.
    fn run(expr: AtomView<'_>) -> Atom {
        // Force Symbolica to register epsilon as antisymmetric before any
        // builders below create new epsilon nodes.
        let _ = *EPSILON_SYMBOL;
        if !Self::contains_epsilon(expr) {
            return expr.to_owned();
        }

        let mut current = expr.schoonschip();

        loop {
            let mut changed = false;
            let next = current.replace_map(|term, _context, out| {
                let rewritten = match term {
                    AtomView::Pow(_) => Self::simplify_power(term),
                    AtomView::Mul(_) => Self::simplify_pair_product(term),
                    _ => None,
                };
                if let Some(rewritten) = rewritten {
                    changed = true;
                    **out = rewritten;
                }
            });
            if !changed {
                return next;
            }

            // Epsilon identities introduce determinants whose metrics may now
            // contract. Unchanged visits need no further tensor normalization.
            let next = next.schoonschip();
            if next == current {
                return next;
            }

            current = next;
        }
    }

    fn contains_epsilon(expr: AtomView<'_>) -> bool {
        match expr {
            AtomView::Fun(f) => {
                f.get_symbol() == *EPSILON_SYMBOL || f.iter().any(Self::contains_epsilon)
            }
            AtomView::Add(add) => add.iter().any(Self::contains_epsilon),
            AtomView::Mul(mul) => mul.iter().any(Self::contains_epsilon),
            AtomView::Pow(pow) => pow.iter().any(Self::contains_epsilon),
            AtomView::Num(_) | AtomView::Var(_) => false,
        }
    }

    /// Applies the repeated-epsilon identity to powers:
    /// `epsilon(a_1,...,a_n)^k -> det(g(a_i,a_j)) epsilon(a_1,...,a_n)^(k-2)`.
    ///
    /// This handles the common canonical form where Symbolica has already
    /// merged an epsilon product into a positive integer power.
    fn simplify_power(expr: AtomView<'_>) -> Option<Atom> {
        let AtomView::Pow(pow) = expr else {
            return None;
        };
        let (base, exponent) = pow.get_base_exp();
        let exponent = Self::positive_integer(exponent)?;
        if exponent < 2 {
            return None;
        }
        let (epsilon_args, representation) = Self::epsilon_args(base)?;
        if !representation.rep.is_self_dual() {
            return None;
        }

        Some(
            Self::metric_determinant(&epsilon_args, &epsilon_args)
                * Self::power(base, exponent - 2),
        )
    }

    /// Applies the epsilon-pair contraction:
    /// `epsilon(a_1,...,a_n) epsilon(b_1,...,b_n) -> det(g(a_i,b_j))`.
    ///
    /// Extra multiplicative factors are preserved around the determinant.
    fn simplify_pair_product(expr: AtomView<'_>) -> Option<Atom> {
        let AtomView::Mul(product) = expr else {
            return None;
        };
        let mut epsilons = product
            .iter()
            .enumerate()
            .filter(|(_, factor)| {
                matches!(factor, AtomView::Fun(fun) if fun.get_symbol() == *EPSILON_SYMBOL)
            })
            .peekable();

        while let Some((left_index, left)) = epsilons.next() {
            // A lone epsilon needs no representation parsing or owned arguments.
            epsilons.peek()?;
            let Some((left_args, left_rep)) = Self::epsilon_args(left) else {
                continue;
            };

            for (right_index, right) in epsilons.clone() {
                let Some((right_args, right_rep)) = Self::epsilon_args(right) else {
                    continue;
                };
                // A determinant pairs a representation with its dual. In
                // particular, two SU(3) triplet epsilons cannot contract.
                if left_args.len() != right_args.len() || left_rep.dual() != right_rep {
                    continue;
                }

                let determinant = Self::metric_determinant(&left_args, &right_args);
                let spectators =
                    Atom::mul_many(product.iter().enumerate().filter_map(|(index, factor)| {
                        (index != left_index && index != right_index).then_some(factor)
                    }));
                return Some(spectators * determinant);
            }
        }

        None
    }

    fn positive_integer(expr: AtomView<'_>) -> Option<i64> {
        let AtomView::Num(number) = expr else {
            return None;
        };
        let CoefficientView::Natural(value, 1, 0, 1) = number.get_coeff_view() else {
            return None;
        };

        (value > 0).then_some(value)
    }

    fn power(base: AtomView<'_>, exponent: i64) -> Atom {
        match exponent {
            0 => Atom::num(1),
            1 => base.to_owned(),
            _ => base.to_owned().pow(Atom::num(exponent)),
        }
    }

    /// Emits the determinant `det(g(left_i,right_j))` by summing over all
    /// signed permutations of the right indices.
    fn metric_determinant(left: &[Atom], right: &[Atom]) -> Atom {
        let mut permutation = (0..right.len()).collect::<Vec<_>>();
        let mut sum = Atom::Zero;
        Self::determinant_terms(left, right, 0, &mut permutation, 1, &mut sum);
        sum
    }

    fn determinant_terms(
        left: &[Atom],
        right: &[Atom],
        position: usize,
        permutation: &mut [usize],
        sign: i64,
        sum: &mut Atom,
    ) {
        if position == permutation.len() {
            let term = left
                .iter()
                .enumerate()
                .fold(Atom::num(sign), |product, (i, arg)| {
                    product * g!(arg.clone(), right[permutation[i]].clone())
                });
            *sum += term;
            return;
        }

        for i in position..permutation.len() {
            permutation.swap(position, i);
            let next_sign = if i == position { sign } else { -sign };
            Self::determinant_terms(left, right, position + 1, permutation, next_sign, sum);
            permutation.swap(position, i);
        }
    }

    fn epsilon_args(epsilon: AtomView<'_>) -> Option<(Vec<Atom>, Representation<LibraryRep>)> {
        let AtomView::Fun(f) = epsilon else {
            return None;
        };
        if f.get_symbol() != *EPSILON_SYMBOL {
            return None;
        }

        let mut representation = None;
        let mut args = Vec::with_capacity(f.get_nargs());
        for arg in f.iter() {
            let rep = Representation::<LibraryRep>::try_from(arg)
                .ok()
                .or_else(|| {
                    // Compact vectors can have ordinary Symbolica heads and
                    // scalar labels, but expose exactly one bare representation.
                    let AtomView::Fun(vector) = arg else {
                        return None;
                    };
                    if vector.get_symbol().is_scalar() {
                        return None;
                    }
                    let mut reps = vector.iter().filter_map(|argument| {
                        Representation::<LibraryRep>::try_from(argument)
                            .ok()
                            .map(|rep| (argument, rep))
                    });
                    let (rep_arg, rep) = reps.next()?;
                    if reps.next().is_some()
                        || Slot::<LibraryRep, AbstractIndex>::try_from(rep_arg).is_ok()
                        || vector.iter().any(|argument| {
                            argument != rep_arg
                                && (argument.is_tensorial(StrictTensorFilter::Tagged)
                                    || argument.is_tensorial(StrictTensorFilter::ContainsReps))
                        })
                    {
                        return None;
                    }
                    Some(rep)
                })?;
            if representation.is_some_and(|previous| previous != rep) {
                return None;
            }
            representation = Some(rep);
            args.push(arg.to_owned());
        }
        let representation = representation?;
        if !representation.rep.is_self_dual()
            && representation.dim != Dimension::Concrete(args.len())
        {
            return None;
        }
        Some((args, representation))
    }
}


pub(crate) fn contains(view: AtomView<'_>) -> bool {
    EpsilonSimplifierPass::contains_epsilon(view)
}
pub(crate) fn candidate_walk(view: AtomView<'_>) -> (Atom, bool) {
    let mut changed = false;
    let next = view.replace_map(|term, _, out| {
        let rewritten = match term {
            AtomView::Pow(_) => EpsilonSimplifierPass::simplify_power(term),
            AtomView::Mul(_) => EpsilonSimplifierPass::simplify_pair_product(term),
            _ => None,
        };
        if let Some(rewritten) = rewritten {
            changed = true;
            **out = rewritten;
        }
    });
    (next, changed)
}

